// Maintain cached state of all AC inputs
let state = context.get('ac_state') || {
    house_source: 'OFF',
    ac_source: 'OFF',
    mastervolt_inverter: 'OFF',
    house_voltage: 0,
    ac_voltage: 0,
    last_updated: null
};

if (msg.topic && msg.topic.includes('HousePanelAppliedSourceText')) {
    state.house_source = msg.payload || 'OFF';
} else if (msg.topic && msg.topic.includes('MastervoltInverterStateText')) {
    state.mastervolt_inverter = msg.payload || 'OFF';
} else if (msg.topic && msg.topic.includes('AcPanelAppliedSourceText')) {
    state.ac_source = msg.payload || 'OFF';
} else if (msg.topic && msg.topic.includes('HousePanelVoltage')) {
    state.house_voltage = parseFloat(msg.payload) || 0;
} else if (msg.topic && msg.topic.includes('AcPanelVoltage')) {
    state.ac_voltage = parseFloat(msg.payload) || 0;
}

state.last_updated = new Date().toISOString();
context.set('ac_state', state);

let summary = 'House: ' + state.house_source + ' (' + state.house_voltage + 'V) | ' +
              'A/C: ' + state.ac_source + ' (' + state.ac_voltage + 'V) | ' +
              'Mastervolt 2000W: ' + state.mastervolt_inverter;

node.status({
    fill: (state.mastervolt_inverter === 'ON' || state.house_source !== 'OFF') ? 'green' : 'grey',
    shape: 'dot',
    text: summary
});

msg.payload = {
    summary: summary,
    house: {
        source: state.house_source,
        voltage_v: state.house_voltage,
        active: state.house_source !== 'OFF' || state.house_voltage > 50
    },
    air_conditioning: {
        source: state.ac_source,
        voltage_v: state.ac_voltage,
        active: state.ac_source !== 'OFF' || state.ac_voltage > 50
    },
    mastervolt_inverter: {
        state: state.mastervolt_inverter,
        inverting: state.mastervolt_inverter === 'ON'
    },
    timestamp: state.last_updated
};

return msg;
